// Languages: English + 9 Indian languages (everyday, spoken style - not textbook words).
// Menus, buttons, police / shop messages and Vikram's spoken reminders are translated.
// Story dialogue stays in Hinglish. Voices: the phone's own voice for each language.
export const LANGS = [
  { id: 'en', en: 'English', name: 'English', tag: 'en-IN' }, { id: 'hi', en: 'Hindi', name: 'हिन्दी', tag: 'hi-IN' }, { id: 'te', en: 'Telugu', name: 'తెలుగు', tag: 'te-IN' },
  { id: 'ta', en: 'Tamil', name: 'தமிழ்', tag: 'ta-IN' }, { id: 'kn', en: 'Kannada', name: 'ಕನ್ನಡ', tag: 'kn-IN' }, { id: 'ml', en: 'Malayalam', name: 'മലയാളം', tag: 'ml-IN' },
  { id: 'gu', en: 'Gujarati', name: 'ગુજરાતી', tag: 'gu-IN' }, { id: 'mr', en: 'Marathi', name: 'मराठी', tag: 'mr-IN' }, { id: 'bn', en: 'Bengali', name: 'বাংলা', tag: 'bn-IN' },
  { id: 'or', en: 'Odia', name: 'ଓଡ଼ିଆ', tag: 'or-IN' },
];
const ORDER = ['hi', 'te', 'ta', 'kn', 'ml', 'gu', 'mr', 'bn', 'or'];
let lang = 'en';
export const getLang = () => lang;
export const langTag = (id = lang) => (LANGS.find((l) => l.id === id) || LANGS[0]).tag;
export const langName = (id = lang) => (LANGS.find((l) => l.id === id) || LANGS[0]).name;
export function setLang(id) { lang = LANGS.some((l) => l.id === id) ? id : 'en'; }
// The phone's own language, if we have it (else English).
export function defaultLang() {
  const n = String((typeof navigator !== 'undefined' && navigator.language) || 'en').slice(0, 2).toLowerCase();
  return n === 'od' ? 'or' : LANGS.some((l) => l.id === n) ? n : 'en';
}
// The game's menus, buttons, settings and messages are always in English (v9.5). Only VOICES and
// Vikram's REMINDER TEXT use the chosen language. t() turns a few message keys into English words.
const EN = {
  VOICE_OK: 'Phone voice ready ✓', VOICE_MISSING: 'No voice for this language on this device, so the game stays silent. Add the voice to hear Vikram.',
  VOICE_TIP: 'Best voices: the Android app. On PC, the Edge browser has natural voices for all these languages.',
  STORY_NOTE: 'Vikram\'s reminders and everyone\'s voices use this language; menus and buttons stay in English. Story scenes: English subtitles.',
  'FREE ROAM OBJECTIVE': null,
};
export function t(en) { return en in EN ? EN[en] : en; }
export function tLabel(label) { return String(label); }
// The page stays English; only the language name on the voice button changes (main.js).
export function applyLanguage() { document.documentElement.lang = 'en'; document.body.classList.remove('lang-in'); }

